import Foundation

nonisolated enum ModelGuidance {
    static let bundledSkillNames: Set<String> = ["evolve","import-memory","manage-providers","manage-skills","visualize"]
    static let fileSystemSchemas: [(String, JSONValue)] = {
        let data = Data("{\"ox.fs.list\":{\"description\":\"List one directory in the active Profile's virtual filesystem: `await ox.fs.list({ purpose, path?, options? })`. The default path is `.`. Bundled System, Profile, and repository workflows share `skills/<name>/SKILL.md`; System skills are read-only. Persisted conversations are read-only under `conversations/<conversation-id>/`. When Files is attached, chosen folders are mounted under `files/<folder-id>/`. Returns virtual paths only; local paths are never exposed.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"Virtual filesystem path, relative or absolute.\"},\"options\":{\"type\":\"object\",\"properties\":{\"limit\":{\"type\":\"integer\",\"description\":\"Maximum entries.\",\"minimum\":1,\"maximum\":100}},\"required\":[],\"additionalProperties\":false},\"purpose\":{\"type\":\"string\",\"description\":\"Optional short step label.\",\"minLength\":1,\"maxLength\":80}},\"required\":[],\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"items\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"Virtual filesystem path, relative or absolute.\"},\"name\":{\"type\":\"string\",\"description\":\"Final component.\"},\"type\":{\"type\":\"string\",\"enum\":[\"file\",\"directory\"]},\"size\":{\"type\":[\"integer\",\"null\"]}},\"required\":[\"path\",\"name\",\"type\",\"size\"],\"additionalProperties\":false}},\"truncated\":{\"type\":\"boolean\",\"description\":\"More entries remain.\"}},\"required\":[\"items\",\"truncated\"],\"additionalProperties\":false}},\"ox.fs.read\":{\"description\":\"Read text with Pi's schema: `await ox.fs.read({ path, offset?, limit?, purpose? })`. offset is one-indexed; limit is the maximum number of lines. Each response is bounded to 2,000 lines or 50 KiB, whichever comes first. Use nextOffset and diagnostics to continue until complete; never infer a complete read from clipped output. The host extracts PDF text before line pagination. A 32 MiB source-file safety limit applies. Reading `skills/<name>/SKILL.md` activates the resolved skill; bundled System skills and their references are read-only. System names cannot be shadowed, and copies are ordinary Profile skills. Conversation metadata and transcripts are read-only snapshots (current for loaded conversations, saved for unloaded conversations) under `conversations/<conversation-id>/{conversation.json,turns.jsonl}`; runtime `context.json` is private. Images return guidance for local `ox.vision.analyze` or explicit `ox.fs.attach`; this read never uploads original pixels. Unsupported binary formats require conversion.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"path\"],\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"Path to the file to read (relative or absolute)\"},\"offset\":{\"type\":\"number\",\"description\":\"Line number to start reading from (1-indexed)\"},\"limit\":{\"type\":\"number\",\"description\":\"Maximum number of lines to read\"},\"purpose\":{\"type\":\"string\",\"description\":\"Optional short step label.\",\"minLength\":1,\"maxLength\":80}},\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"Virtual filesystem path, relative or absolute.\"},\"text\":{\"type\":[\"string\",\"null\"]},\"truncated\":{\"type\":\"boolean\",\"description\":\"More text remains.\"},\"unsupported\":{\"type\":[\"string\",\"null\"]},\"nextOffset\":{\"type\":[\"integer\",\"null\"]},\"diagnostics\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"severity\":{\"type\":\"string\",\"description\":\"Severity.\"},\"code\":{\"type\":\"string\",\"description\":\"Diagnostic code.\"},\"message\":{\"type\":\"string\",\"description\":\"Diagnostic.\"}},\"required\":[\"severity\",\"message\"],\"additionalProperties\":false}}},\"required\":[\"path\",\"text\",\"truncated\",\"unsupported\",\"nextOffset\",\"diagnostics\"],\"additionalProperties\":false}},\"ox.fs.write\":{\"description\":\"Write one UTF-8 file with Pi's schema: `await ox.fs.write({ path, content, purpose? })`. Host writes are atomic. Artifacts are immutable and require a distinct filename for each version. The writable virtual layout is `MEMORY.md`, `SOUL.md`, `artifacts/<filename>`, writable `skills/<name>/SKILL.md` and their `references/` and `scripts/` resources, Local service source under `services/<kind>/<id>/...`, and files inside an attached chosen folder at `files/<folder-id>/...`. Bundled service source is read-only, while Development and Remote services expose only read-only manifests. Persisted conversations, bundled System skills, compatibility snapshots, and installed repository skills are read-only. Skill ownership and source selection determine write access.\\n\\nRead before overwriting an existing file and prefer `ox.fs.edit` for targeted changes. Writing or editing inside a chosen Files folder requires its attached Files service and existing folder grant. All writes follow the user's Action policies and source permissions; activation does not replace approval. Create or change artifacts when the user wants a durable result or when the user wants a Canvas for a visual result, interactive experience, or small app. Write Markdown notes as artifacts/<name>.md and read skills/visualize/SKILL.md for HTML canvases. New artifact writes display automatically; preserve valid requested filenames and report the final path. Revisions require a new filename. These operations edit UTF-8 text, not arbitrary binary formats.\\n\\nLocal service file operations enforce filesystem safety without validating service contents or reloading running attachments. Finish related source changes in any order, then call `ox.service.validate` to check the whole draft and `ox.service.attach` to reload this conversation's attachment. Attach and Save require a valid complete service.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"path\",\"content\"],\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"Path to the file to write (relative or absolute)\"},\"content\":{\"type\":\"string\",\"description\":\"Content to write to the file\"},\"purpose\":{\"type\":\"string\",\"description\":\"Optional short step label.\",\"minLength\":1,\"maxLength\":80}},\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"Virtual filesystem path, relative or absolute.\"},\"name\":{\"type\":\"string\",\"description\":\"Final component.\"},\"type\":{\"type\":\"string\",\"enum\":[\"file\",\"directory\"]},\"size\":{\"type\":[\"integer\",\"null\"]}},\"required\":[\"path\",\"name\",\"type\",\"size\"],\"additionalProperties\":false}},\"ox.fs.edit\":{\"description\":\"Edit one UTF-8 file with Pi's schema: `await ox.fs.edit({ path, edits: [{ oldText, newText }], purpose? })`. Every edit is matched against the original file, not after earlier edits. oldText must be non-empty, unique, and non-overlapping; keep it small while unique. Merge nearby changes into one edit. Line endings are preserved. The host rejects a concurrent change rather than overwriting it. Returns file metadata, diff, patch, and firstChangedLine. Existing artifacts are immutable: read the old version, then write the edited content under a new filename.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"path\",\"edits\"],\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"Path to the file to edit (relative or absolute)\"},\"edits\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"required\":[\"oldText\",\"newText\"],\"properties\":{\"oldText\":{\"type\":\"string\",\"description\":\"Exact text for one targeted replacement. It must be unique in the original file and must not overlap with any other edits[].oldText in the same call.\"},\"newText\":{\"type\":\"string\",\"description\":\"Replacement text for this targeted edit.\"}}},\"description\":\"One or more targeted replacements. Each edit is matched against the original file, not incrementally. Do not include overlapping or nested edits. If two changes touch the same block or nearby lines, merge them into one edit instead.\"},\"purpose\":{\"type\":\"string\",\"description\":\"Optional short step label.\",\"minLength\":1,\"maxLength\":80}},\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"Virtual filesystem path, relative or absolute.\"},\"name\":{\"type\":\"string\",\"description\":\"Final component.\"},\"type\":{\"type\":\"string\",\"enum\":[\"file\",\"directory\"]},\"size\":{\"type\":[\"integer\",\"null\"]},\"diff\":{\"type\":\"string\",\"description\":\"Changed lines.\"},\"patch\":{\"type\":\"string\",\"description\":\"Unified patch.\"},\"firstChangedLine\":{\"type\":\"integer\",\"description\":\"First changed line.\",\"minimum\":1,\"maximum\":9007199254740991}},\"required\":[\"path\",\"name\",\"type\",\"size\",\"diff\",\"patch\"],\"additionalProperties\":false}},\"ox.fs.delete\":{\"description\":\"Delete one artifact, Profile-owned skill, Local service source file, or file inside a chosen Files folder: `await ox.fs.delete({ purpose, path })`. Read or inspect the existing item before deletion. Resource roots such as Local services use their `ox.service.delete` lifecycle function. Deleting inside a chosen Files folder requires approval unless the user has allowed that action without asking. `MEMORY.md`, `SOUL.md`, and chosen folders themselves cannot be deleted.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"Virtual filesystem path, relative or absolute.\"},\"purpose\":{\"type\":\"string\",\"description\":\"Optional short step label.\",\"minLength\":1,\"maxLength\":80}},\"required\":[\"path\"],\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"Virtual filesystem path, relative or absolute.\"},\"deleted\":{\"type\":\"boolean\",\"description\":\"Deleted.\"}},\"required\":[\"path\",\"deleted\"],\"additionalProperties\":false}},\"ox.fs.glob\":{\"description\":\"Find file paths by glob: `await ox.fs.glob({ purpose, pattern, path?, options? })`. Supports `*`, `**`, and `?`. The optional directory path bounds the search; results are full virtual paths.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"Virtual filesystem path, relative or absolute.\"},\"pattern\":{\"type\":\"string\",\"description\":\"Glob supporting *, **, and ?.\"},\"purpose\":{\"type\":\"string\",\"description\":\"Optional short step label.\",\"minLength\":1,\"maxLength\":80},\"options\":{\"type\":\"object\",\"properties\":{\"limit\":{\"type\":\"integer\",\"description\":\"Maximum paths.\",\"minimum\":1,\"maximum\":1000}},\"required\":[],\"additionalProperties\":false}},\"required\":[\"pattern\"],\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"paths\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"description\":\"Virtual filesystem path, relative or absolute.\"}},\"truncated\":{\"type\":\"boolean\",\"description\":\"More paths remain.\"}},\"required\":[\"paths\",\"truncated\"],\"additionalProperties\":false}},\"ox.fs.grep\":{\"description\":\"Search text inside files using bounded linear-time RE2 expressions (backreferences and unsupported lookarounds are rejected): `await ox.fs.grep({ purpose, pattern, path?, options? })`. The optional `glob` filters candidate paths. Persisted conversation transcripts are searched only when `path` explicitly names `conversations` or one of its descendants; a root search does not sweep conversation history. Matching excerpts are centered on the match. Unsupported binary artifacts are skipped.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"Virtual filesystem path, relative or absolute.\"},\"pattern\":{\"type\":\"string\",\"description\":\"Regular expression or literal text.\"},\"purpose\":{\"type\":\"string\",\"description\":\"Optional short step label.\",\"minLength\":1,\"maxLength\":80},\"options\":{\"type\":\"object\",\"properties\":{\"limit\":{\"type\":\"integer\",\"description\":\"Maximum matches.\",\"minimum\":1,\"maximum\":200},\"glob\":{\"type\":\"string\",\"description\":\"Path glob.\"},\"ignoreCase\":{\"type\":\"boolean\",\"description\":\"Ignore case.\"},\"literal\":{\"type\":\"boolean\",\"description\":\"Literal search.\"},\"contextLines\":{\"type\":\"integer\",\"description\":\"Context lines.\",\"minimum\":0,\"maximum\":5}},\"required\":[],\"additionalProperties\":false}},\"required\":[\"pattern\"],\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"matches\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"Virtual filesystem path, relative or absolute.\"},\"line\":{\"type\":\"integer\",\"description\":\"Line number.\",\"minimum\":1,\"maximum\":9007199254740991},\"text\":{\"type\":\"string\",\"description\":\"Matched excerpt.\"},\"before\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"description\":\"Context.\"}},\"after\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"description\":\"Context.\"}}},\"required\":[\"path\",\"line\",\"text\",\"before\",\"after\"],\"additionalProperties\":false}},\"scannedFiles\":{\"type\":\"integer\",\"description\":\"Scanned files.\",\"minimum\":0,\"maximum\":1000},\"skippedFiles\":{\"type\":\"integer\",\"description\":\"Unsupported files.\",\"minimum\":0,\"maximum\":1000},\"truncated\":{\"type\":\"boolean\",\"description\":\"Search limit reached.\"}},\"required\":[\"matches\",\"scannedFiles\",\"skippedFiles\",\"truncated\"],\"additionalProperties\":false}},\"ox.fs.attach\":{\"description\":\"Attach an immutable snapshot of one file to model context: `await ox.fs.attach({ purpose, path })`. Accepts `artifacts/<filename>`, `files/<folder-id>/<file>` inside a selected folder when Files is attached, or a public HTTP(S) URL (including the `url` returned by `ox.web.fetch`). URLs are fetched at attachment time with the same credential-free request policy and execution limits as `ox.web.fetch`; content may have changed since an earlier fetch. Supports images, PDFs, UTF-8 text (including HTML, JSON, CSV, and source code), and other files subject to the selected provider's format support. Acceptance by Ox does not guarantee the model can consume a binary format; convert unsupported files or switch to a compatible provider. This explicitly makes content available to the selected model/provider; it does not present the file in conversation or modify the source. Prefer `ox.fs.read` for text and PDF text, or `ox.vision.analyze` for local image OCR and classification. Virtual source files are limited to 10 MiB. URL fetches share the web execution byte limit; prepared attachments share the execution limit of four transient attachments and 20 MiB total. For models without image input, adapters may substitute local OCR/classification. Unsupported PDF input fails explicitly.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"File path or public HTTP(S) URL.\"},\"purpose\":{\"type\":\"string\",\"description\":\"Optional short step label.\",\"minLength\":1,\"maxLength\":80}},\"required\":[\"path\"],\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"filename\":{\"type\":\"string\",\"description\":\"Filename.\"},\"contentType\":{\"type\":\"string\",\"description\":\"MIME type.\"},\"bytes\":{\"type\":\"integer\",\"description\":\"Attachment bytes.\",\"minimum\":1,\"maximum\":20971520},\"kind\":{\"type\":\"string\",\"enum\":[\"image\",\"pdf\",\"text\",\"file\"]}},\"required\":[\"filename\",\"contentType\",\"bytes\",\"kind\"],\"additionalProperties\":false}}}".utf8)
        guard let schemas = try? JSONDecoder().decode(JSONValue.self, from: data).objectValue else {
            preconditionFailure("Invalid agent filesystem schemas")
        }
        return schemas.sorted { $0.key < $1.key }.map { ($0.key, $0.value) }
    }()
    private static let texts: [String: String] = [
